import { runInNewContext } from "node:vm";
import { describe, expect, it } from "vitest";
import { isWorkspacePath } from "@/lib/appearance";
import { themeScript } from "@/lib/theme";

function boot(
  pathname: string,
  saved: Record<string, string> = {},
  access: { allowed: boolean; deadline: string | null } = {
    allowed: false,
    deadline: null,
  },
  blocked = false,
) {
  const attributes = new Set<string>();
  const dataset: Record<string, string> = {};
  let themeColor: string | null = null;
  const document = {
    documentElement: {
      dataset,
      toggleAttribute: (key: string, value: boolean) =>
        value ? attributes.add(key) : attributes.delete(key),
    },
    querySelector: () => ({
      setAttribute: (_key: string, value: string) => {
        themeColor = value;
      },
    }),
  };
  runInNewContext(themeScript(access), {
    document,
    location: { pathname },
    localStorage: {
      getItem: (key: string) => {
        if (blocked) throw new Error("Storage blocked");
        return saved[key] ?? null;
      },
    },
  });
  return {
    appearance: dataset.appearance,
    theme: dataset.theme,
    themeColor,
    workspace: attributes.has("data-workspace"),
  };
}

describe("appearance initialization before hydration", () => {
  for (const [appearance, theme, color] of [
    ["purple", "light", "#f6f5fb"],
    ["purple", "dark", "#0b0a14"],
    ["vercel", "light", "#fafafa"],
    ["vercel", "dark", "#0a0a0a"],
  ]) {
    it(`starts in ${appearance} ${theme} when access is verified`, () => {
      expect(
        boot(
          "/compose",
          { "mailloop-appearance": appearance, "mailloop-theme": theme },
          { allowed: true, deadline: null },
        ),
      ).toEqual({ appearance, theme, themeColor: color, workspace: true });
    });
  }
  it("defaults to Purple Dark", () => {
    expect(boot("/contacts")).toEqual({
      appearance: "purple",
      theme: "dark",
      themeColor: "#0b0a14",
      workspace: true,
    });
    expect(boot("/").theme).toBe("dark");
  });
  it("keeps Premium appearance locked when access is denied or expired", () => {
    const saved = {
      "mailloop-appearance": "vercel",
      "mailloop-theme": "light",
    };
    expect(boot("/compose", saved)).toMatchObject({
      appearance: "purple",
      theme: "light",
    });
    expect(
      boot("/compose", saved, {
        allowed: true,
        deadline: new Date(Date.now() - 1000).toISOString(),
      }),
    ).toMatchObject({ appearance: "purple", theme: "light" });
  });
  it("falls back safely for invalid preferences and blocked storage", () => {
    expect(
      boot(
        "/settings",
        { "mailloop-appearance": "invalid", "mailloop-theme": "invalid" },
        { allowed: true, deadline: null },
      ),
    ).toMatchObject({ appearance: "purple", theme: "dark", workspace: true });
    expect(boot("/usage", {}, { allowed: true, deadline: null }, true)).toEqual({
      appearance: "purple",
      theme: "dark",
      themeColor: "#0b0a14",
      workspace: true,
    });
  });
  it("retains the choice but never activates workspace styles on public or admin routes", () => {
    for (const path of [
      "/",
      "/pricing",
      "/privacy",
      "/terms",
      "/admin",
      "/admin/users",
      "/contacts-other",
      "/usage/return",
      "/usage/return/",
    ]) {
      expect(boot(path, { "mailloop-appearance": "vercel" }).workspace).toBe(
        false,
      );
      expect(isWorkspacePath(path)).toBe(false);
    }
    for (const path of [
      "/compose",
      "/contacts",
      "/templates",
      "/history",
      "/usage",
      "/settings",
      "/billing",
      "/settings/billing/return",
    ]) {
      expect(boot(path).workspace).toBe(true);
      expect(isWorkspacePath(path)).toBe(true);
    }
  });
});
